        reflector_couplings.data_ptr<float>());
    tridiagonal_eigenvalues<128, 352><<<
        batch * 3, 128, 3 * n * sizeof(float)>>>(
        diagonal.data_ptr<float>(), off_diagonal.data_ptr<float>(),
        values.data_ptr<float>(), info.data_ptr<int>());
    tridiagonal_inverse_iteration<kInversePairs, kInversePitch, 352><<<
        batch * 6, kInversePairs, inverse_shared>>>(
