        column_reflectors.data_ptr<float>(), taus.data_ptr<float>(),
        reflector_couplings.data_ptr<float>(), vectors.data_ptr<float>());
  } else {
    const int reduce_shared = (2 * n + 32) * sizeof(float);
    const int solve_shared = (2 * n + 2 * n * 17) * sizeof(float);
    cudaFuncSetAttribute(
        tridiagonal_eigh_and_backtransform<16, 8, 17, 25, false, false>,
        cudaFuncAttributeMaxDynamicSharedMemorySize, solve_shared);
