        input.data_ptr<float>(), packed_reflectors.data_ptr<float>(), n);
    reduce_global_to_tridiagonal<true, 8><<<batch, 1024, reduce_shared>>>(
        packed_reflectors.data_ptr<float>(), diagonal.data_ptr<float>(),
        off_diagonal.data_ptr<float>(), taus.data_ptr<float>(), n);
    tridiagonal_eigh_and_backtransform<16, 8, 17, 25, false, false><<<
