        off_diagonal.data_ptr<float>(), taus.data_ptr<float>(),
        vectors.data_ptr<float>(), values.data_ptr<float>(),
        info.data_ptr<int>(), n);
    unpack_lower_triangle<<<batch, 256>>>(
        packed_reflectors.data_ptr<float>(), reflectors.data_ptr<float>(), n);
  }
  return {vectors, values, reflectors, taus};
}

