std::vector<torch::Tensor> jacobi32(torch::Tensor input) {
  TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
  TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be FP32");
  TORCH_CHECK(input.dim() == 3 && input.size(1) == 32 && input.size(2) == 32,
              "jacobi32 requires shape [batch, 32, 32]");
  const c10::cuda::CUDAGuard device_guard(input.device());
  const int batch = static_cast<int>(input.size(0));
  auto vectors = torch::empty_like(input);
  auto values = torch::empty({input.size(0), 32}, input.options());
  constexpr int shared_bytes = 4896 * sizeof(float);
  cudaFuncSetAttribute(fused_householder_eigh32,
                       cudaFuncAttributeMaxDynamicSharedMemorySize,
                       shared_bytes);
  fused_householder_eigh32<<<batch, 512, shared_bytes>>>(
      input.data_ptr<float>(), vectors.data_ptr<float>(),
      values.data_ptr<float>());
